#define TWO_PI 6.28318530

vec2 distanceToSegment( vec2 a, vec2 b, vec2 p )
{
	vec2 pa = p - a, ba = b - a;
	float h = clamp( dot(pa,ba)/dot(ba,ba), 0.0, 1.0 );
	return vec2(length( pa - ba*h ), h);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
	vec2 p = fragCoord / iResolution.x;
    vec2 cen = 0.5*iResolution.xy/iResolution.x;
    vec4 m = iMouse / iResolution.x;

	vec3 col = vec3(0.0);

	if( m.z>0.0 ) // button is down
	{
		vec2 res = distanceToSegment( m.xy, abs(m.zw), p );
        float line_len = length(m.xy - m.zw);
        float freq = 4.0 * line_len;
        float width = sin(-iTime + res[1] * TWO_PI * freq) / 2.0 + 3.0;
        float border_d = 0.01 * width;
        border_d *= res[1] * line_len * 2.0;
        float d = res[0];
        vec3 intColor = mix(vec3(1.0, 0.0, 0.0), vec3(1.0, 1.0, 0.0), res[1]);
        float border_smooth = smoothstep(border_d - .01, border_d, d) - smoothstep(border_d, border_d + .01, d);
        col = mix( col, intColor, border_smooth );

	}

	fragColor = vec4( col, 1.0 );
}
